function [changes, last, st] = switches(st, k)
%SWITCHES  The kind seen last, as a state, and how often it changed.
%   k: Device (passed a choice, as its option's number)
%   returns changes: int (passed a whole number)
%   returns last: Device (passed a choice, as its option's number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    if isempty(st)
        st = struct();
        st.was = 1;
        st.n = 0;
    end
    changes = 0;
    last = 0;
    if (k ~= st.was)
        st.n = (st.n + 1);
    end
    st.was = k;
    changes = st.n;
    last = st.was;
end
